extends Node2D
@export var grid_width := 10
@export var grid_height := 5
const CELL_SIZE := 64
const GRID_COLOR = Color.WHITE

var cells: Dictionary[Vector2i, String] = {}

func _ready() -> void:
	#TEMP
	cells[Vector2i(0,0)] = "hello"
	cells[Vector2i(5,3)] = "my"
	cells[Vector2i(2,4)] = "world"
	cells.erase(Vector2i(2,4))

# Runs one time at start
func _draw() -> void:
	var cell_dimension := Vector2(CELL_SIZE, CELL_SIZE)

	#TEMP
	for cell: Vector2i in cells.keys():
		draw_rect(Rect2(Vector2(cell)*CELL_SIZE, cell_dimension), Color.DARK_RED)

	# draw each cell of the grid
	for x in grid_width:
		for y in grid_height:
			var cell_coordinates := Vector2(x,y) * CELL_SIZE
			draw_rect(Rect2(cell_coordinates, cell_dimension), GRID_COLOR, false)


# Runs every frame
func _process(_delta: float) -> void:
	var cursor = get_global_mouse_position()
	cursor = world_position_to_cell(cursor)
	#TEMP
	print("cell index = ", str(cursor),", in bounds = ",is_in_bounds(cursor), " has item = ", cell_has_item(cursor), ", ", get_cell_item(cursor))


# converts world's position into which local cell you're currently over
# =======================================================================
# a cell is represented as a vector2i(x,y) because each cell is located in a 2d grid 
# so you need an x and y to determine which cell you are in 
func world_position_to_cell(world_position: Vector2) -> Vector2i:
	# change origin point from world to local node
	var local_position := to_local(world_position)

	# convert position from virtual pixel to grid cell index	
	var cell = local_position / CELL_SIZE
	cell = cell.floor()
	return Vector2i(cell)

# checks if cell position is inside grid bounds
func is_in_bounds(cell: Vector2i) -> bool:
	if cell.x < 0 || cell.x >= grid_width:
		return false

	if cell.y < 0 || cell.y >= grid_height:
		return false

	return true

# Cell Dictionary Helpers
func cell_has_item(cell: Vector2i) -> bool:
	return cells.has(cell)

func get_cell_item(cell: Vector2i):
	return cells.get(cell, null)
